          "reason": "Sự kết hợp giữa áo cổ V cotton lụa và chân váy xếp ly tơ đũi tạo nền tảng tốt cho họa tiết thêu gấu váy lấy cảm hứng từ tranh Đông Hồ."
        },
        {
          "criterion_id": "focal_balance",
          "applicable": true,
          "rating": 4,
          "reason": "Điểm nhấn đặt ở gấu chân váy tạo sự chuyển động uyển chuyển, tuy nhiên cần kiểm soát độ phồng của tơ đũi xếp ly để duy trì sự gọn gàng."
        },
        {
          "criterion_id": "contextual_coherence",
          "applicable": true,
          "rating": 5,
          "reason": "Gam màu vàng nhạt và trắng kem trẻ trung, thanh lịch, rất phù hợp với không gian sự kiện thời trang mùa hè."
        },
        {
          "criterion_id": "conflict_resolution",
          "applicable": true,
          "rating": 4,
          "reason": "Cân bằng tốt giữa phom dáng váy xếp ly bay bổng và đường nét dứt khoát của họa tiết Đông Hồ, đảm bảo tính khả thi."
        }
      ],
      "harmony_score": 88.0,
      "proposed_total": 90.35,
      "cross_domain_conflicts": [
        "Chân váy tơ đũi xếp ly cần được định hình nếp gấp chắc chắn để họa tiết thêu ở gấu váy không bị biến dạng khi người mặc di chuyển."
      ],
      "recommendation": "eligible",
      "summary": "Phương án R5-B3-C2 mang đến giải pháp thiết kế mùa hè tươi trẻ, kết hợp nhịp nhàng giữa chất liệu nhẹ và điểm nhấn mỹ thuật dứt khoát."
    },
